import mime from"mime";import fs from"node:fs";import{pipeline}from"node:stream/promises";import{PublicReturn}from"../../common/public-return.js";import{getGlobalVariables}from"../../action/setup-global-variables.js";export function createRouter(e){const t=getGlobalVariables("sitemapXmlPath"),a=async function(e,a){a.headers({"Content-Type":mime.getType(getGlobalVariables("sitemapXmlPath"))||""});const m=fs.createReadStream(t);m.on("error",e=>{a.code(404).send(new PublicReturn(404,"没找到文件 sitemap.xml"))}),await pipeline(m,a.raw)};e.get("/sitemap.xml",a),e.get("/siteMap.xml",a),e.get("/SiteMap.xml",a)}